pm.test("Status is 200", function () {
    pm.response.to.have.status(200);
});

const previousBooking = JSON.parse(
    pm.environment.get("expectedBooking")
);
const changes = JSON.parse(pm.request.body.raw);
const actualBooking = pm.response.json();

pm.test("Selected fields are updated", function () {
    pm.expect(actualBooking.firstname).to.equal(changes.firstname);
    pm.expect(actualBooking.totalprice).to.equal(changes.totalprice);
});

pm.test("Other booking fields are unchanged", function () {
    pm.expect(actualBooking.lastname)
        .to.equal(previousBooking.lastname);
    pm.expect(actualBooking.depositpaid)
        .to.equal(previousBooking.depositpaid);
    pm.expect(actualBooking.bookingdates)
        .to.deep.equal(previousBooking.bookingdates);
    pm.expect(actualBooking.additionalneeds)
        .to.equal(previousBooking.additionalneeds);
});

if (pm.response.code === 200) {
    const expectedBooking = {
        ...previousBooking,
        ...changes
    };

    pm.environment.set(
        "expectedBooking",
        JSON.stringify(expectedBooking)
    );
}

